#!/bin/bash

# Проверка прав в /srv/www

find /srv/www -type d -exec sh -c 'if [[ "$(stat -c %a {})" != "755" ]]; then echo "Ошибка: каталог $(basename {}) должен иметь права 755"; exit 1; fi' \;

find /srv/www -type f \( -not -name "*.sh" \) -exec sh -c 'if [[ "$(stat -c %a {})" != "644" ]]; then echo "Ошибка: файл $(basename {}) должен иметь права 644"; exit 1; fi' \;

find /srv/www -type f -name "*.sh" -exec sh -c 'if [[ "$(stat -c %a {})" != "755" ]]; then echo "Ошибка: файл $(basename {}) должен иметь права 755"; exit 1; fi' \;

echo "Тест пройден"
exit 0

#!/bin/bash

# Проверяем, что конфигурация logrotate /etc/logrotate.d/app существует
if [ ! -f /etc/logrotate.d/app ]; then
  echo "Файл конфигурации /etc/logrotate.d/app отсутствует."
  exit 1
fi

# Проверяем содержимое файла /etc/logrotate.d/app
grep -q '^/var/log/app/*.log' /etc/logrotate.d/app || {
  echo "Отсутствует директива для файлов /var/log/app/*.log в конфигурации."
  exit 1
}

grep -q 'daily' /etc/logrotate.d/app || {
  echo "Не найдена директива 'daily' в конфигурации."
  exit 1
}

grep -q 'rotate 7' /etc/logrotate.d/app || {
  echo "Не найдена директива 'rotate 7' в конфигурации."
  exit 1
}

grep -q 'compress gzip' /etc/logrotate.d/app || {
  echo "Не найдена директива 'compress gzip' в конфигурации."
  exit 1
}

grep -q 'missingok' /etc/logrotate.d/app || {
  echo "Не найдена директива 'missingok' в конфигурации."
  exit 1
}

grep -q 'nocreate' /etc/logrotate.d/app || {
  echo "Не найдена директива 'nocreate' в конфигурации."
  exit 1
}

# Проверяем, что права на новый файл /var/log/app/*.log установлены как 0640
for file in /var/log/app/*.log; do
  if [[ ! -f "$file" ]] || [[ ! $(stat -c %a "$file") == "0640" ]]; then
    echo "Неправильные права на файл: $file"
    exit 1
  fi
done

echo "Тест пройден."
exit 0
